INSERT INTO `meals` VALUES (1,3,'بالطبع، سأقوم بإعداد خطة غذائية يومية متوازنة تناسب احتياجاتك. يجب أن نأخذ في الاعتبار أن الهدف هو ف',0,'2025-11-15',NULL),(2,3,'بالطبع، سأقدم لك خطة غذائية يومية متوازنة تساعدك في تحقيق هدفك في فقدان الوزن. يجب أن نأخذ في الاعتب',0,'2025-11-15',NULL),(3,3,'بالطبع، سأقدم لك خطة غذائية يومية متوازنة تساعدك في تحقيق هدفك في فقدان الوزن. يجب أن نأخذ في الاعتب',0,'2025-11-15',NULL),(4,3,'بالطبع! إليك خطة غذائية يومية متوازنة تناسب احتياجاتك. تذكر أن هذه الخطة هي مجرد اقتراح، ويجب عليك ا',0,'2025-11-15',NULL),(5,3,'بالطبع! إليك خطة غذائية يومية متوازنة تستند إلى المعلومات التي قدمتها. الهدف هو فقدان الوزن بطريقة ص',0,'2025-11-15',NULL),(6,3,'بالطبع، سأقدم لك خطة غذائية يومية متوازنة تناسب احتياجاتك. يجب أن نأخذ في الاعتبار أن السعرات الحرار',0,'2025-11-15',NULL),(7,4,'بالطبع، سأقوم بإعداد خطة غذائية يومية متوازنة تناسب احتياجاتك. يجب أن نأخذ في الاعتبار أن هدفك هو فق',0,'2025-11-15',NULL),(8,5,'بالطبع! إليك خطة غذائية يومية متوازنة تناسب احتياجاتك. الهدف هو زيادة الوزن بطريقة صحية، لذا سنركز على تناول سعرات حرارية كافية مع التركيز على العناصر الغذائية.\n\n### الخطة الغذائية اليومية\n\n#### الإفطار\n- **شوفان مطبوخ** (50 جرام) مع:\n  - حليب كامل الدسم (200 مل)\n  - موزة واحدة\n  - ملعقة كبيرة من العسل\n- **سعرات تقديرية**: 450 سعر حراري\n\n#### وجبة خفيفة صباحية\n- **حفنة من المكسرات** (30 جرام) (لوز أو جوز)\n- **سعرات تقديرية**: 180 سعر حراري\n\n#### الغداء\n- **صدر دجاج مشوي** (150 جرام)\n- **أرز بني مطبوخ** (100 جرام)\n- **سلطة خضار** (خس، طماطم، خيار، زيت زيتون)\n- **سعرات تقديرية**: 600 سعر حراري\n\n#### وجبة خفيفة بعد الظهر\n- **زبادي كامل الدسم** (200 جرام) مع:\n  - ملعقة كبيرة من العسل\n  - ملعقة صغيرة من القرفة\n- **سعرات تقديرية**: 250 سعر حراري\n\n#### العشاء\n- **سمك مشوي** (150 جرام) (مثل السلمون أو التونة)\n- **بطاطا حلوة مشوية** (150 جرام)\n- **خضار مطبوخة على البخار** (مثل البروكلي أو الجزر)\n- **سعرات تقديرية**: 600 سعر حراري\n\n#### وجبة خفيفة مسائية (اختيارية)\n- **شريحة من خبز الحبوب الكاملة** مع:\n  - ملعقة كبيرة من زبد',0,'2025-11-29','2025-11-29 16:31:17'),(9,7,'بالطبع! إليك خطة غذائية يومية متوازنة تناسب احتياجاتك. يجب أن نأخذ في الاعتبار أن هذه الخطة تهدف إلى فقدان الوزن بطريقة صحية. تذكري أن استشارة أخصائي تغذية أو طبيب هي خطوة مهمة قبل البدء في أي نظام غذائي.\n\n### الخطة الغذائية اليومية\n\n#### الإفطار:\n- **شوفان مطبوخ** (50 جرام) مع:\n  - حليب خالي الدسم (200 مل)\n  - ملعقة صغيرة من العسل\n  - نصف موزة مقطعة\n- **سعرات تقديرية:** 350 سعرة حرارية\n\n#### وجبة خفيفة:\n- **تفاحة واحدة** أو **برتقالة واحدة**\n- **سعرات تقديرية:** 80-100 سعرة حرارية\n\n#### الغداء:\n- **صدر دجاج مشوي** (150 جرام) أو **سمك مشوي** (150 جرام)\n- **كوب من الأرز البني** (150 جرام) أو **كوب من الكينوا**\n- **سلطة خضار** (خس، طماطم، خيار، جزر) مع ملعقة صغيرة من زيت الزيتون وعصير الليمون\n- **سعرات تقديرية:** 600-700 سعرة حرارية\n\n#### وجبة خفيفة:\n- **حفنة من المكسرات** (مثل اللوز أو الجوز) (30 جرام)\n- **سعرات تقديرية:** 180-200 سعرة حرارية\n\n#### العشاء:\n- **شوربة خضار** (كوسا، جزر، بروكلي) مع ملعقة صغيرة من زيت الزيتون\n- **بيضة مسلوقة** أو **150 جرام من التوفو**\n- **شريحة من خبز الحبوب الكاملة** (30 جرام)',0,'2025-11-30','2025-11-30 16:52:55'),(10,6,'بالطبع، سأقوم بإنشاء خطة غذائية يومية متوازنة تناسب احتياجاتك. لكن يجب أن نذكر أن هذه الخطة لا تغني عن استشارة طبيب أو أخصائي تغذية معتمد، خاصةً في حالات فقدان الوزن. من المهم متابعة أي تغييرات في الوزن أو الصحة مع متخصص.\n\n### خطة غذائية يومية\n\n#### الإفطار:\n- **شوفان مطبوخ** (1 كوب) مع حليب خالي الدسم (1/2 كوب) \n- **موزة واحدة** \n- **شاي أخضر** أو **قهوة بدون سكر** \n\n**السعرات التقديرية:** 350-400 سعرة حرارية\n\n#### وجبة خفيفة:\n- **حفنة من اللوز** (حوالي 30 جرام) \n\n**السعرات التقديرية:** 170-200 سعرة حرارية\n\n#### الغداء:\n- **صدر دجاج مشوي** (150 جرام) \n- **أرز بني** (1/2 كوب) \n- **سلطة خضار** (خس، طماطم، خيار، زيت زيتون وليمون) \n\n**السعرات التقديرية:** 500-600 سعرة حرارية\n\n#### وجبة خفيفة:\n- **زبادي خالي الدسم** (1 كوب) مع ملعقة صغيرة من العسل \n\n**السعرات التقديرية:** 150-200 سعرة حرارية\n\n#### العشاء:\n- **سمك مشوي** (150 جرام) \n- **خضار مطبوخة على البخار** (مثل البروكلي أو الجزر) \n- **بطاطا حلوة مشوية** (1/2 حبة) \n\n**السعرات التقديرية:** 500-600 سعرة حرارية\n\n### إجمالي السعرات التقديرية: \nحوالي 1870',0,'2025-12-02','2025-12-02 15:38:01'),(11,6,'من المهم أن نبدأ بالتأكيد على أنني لست بديلاً عن استشارة طبيب أو أخصائي تغذية معتمد. إذا كنت تعاني من أي حالات صحية أو تحتاج إلى خطة غذائية مخصصة، يُفضل استشارة مختص.\n\nبناءً على المعلومات التي قدمتها، يبدو أن هناك خطأ في الوزن والطول، حيث أن الوزن 11 كجم لطول 134 سم غير طبيعي. إذا كان هناك خطأ في البيانات، يرجى تصحيحه. ومع ذلك، سأقدم لك خطة غذائية عامة لزيادة الوزن بشكل صحي.\n\n### خطة غذائية يومية لزيادة الوزن\n\n#### الإفطار:\n- 2 بيضة مسلوقة أو مقلية بزيت الزيتون\n- شريحتان من الخبز الكامل\n- حبة موز\n- كوب من الحليب كامل الدسم\n\n**السعرات التقديرية:** 600-700 سعرة حرارية\n\n#### وجبة خفيفة (سناك):\n- حفنة من المكسرات (لوز أو جوز)\n- 1 تفاحة\n\n**السعرات التقديرية:** 200-300 سعرة حرارية\n\n#### الغداء:\n- 150 جرام من صدور الدجاج المشوية أو اللحم البقري\n- كوب من الأرز البني أو الكينوا\n- سلطة خضار مع زيت الزيتون والليمون\n- حبة بطاطا حلوة مشوية\n\n**السعرات التقديرية:** 700-800 سعرة حرارية\n\n#### وجبة خفيفة (سناك):\n- زبادي كامل الدسم مع ملعقة عسل\n- 1 حبة فاكهة (مثل البرتقال أو الكمثرى)\n\n**السعرات التقديرية:** 200-300 سعرة حرارية\n\n#### العشاء:\n- 150 جرام من السمك المشوي (مثل السلمون أو التونة)\n- كوب',0,'2025-12-02','2025-12-02 16:23:18');
